 "content": "from collections import deque


def transform(grid):
    h, w = len(grid), len(grid[0])
    # The solid 2-line is the platform; objects fall toward it.
    floor_rows = [r for r in range(h) if all(v == 2 for v in grid[r])]
    floor_cols = [c for c in range(w) if all(grid[r][c] == 2 for r in range(h))]
    if floor_rows:
        axis, direction, line = 0, (-1 if floor_rows[0] == 0 else 1), floor_rows[0]
    elif floor_cols:
        axis, direction, line = 1, (-1 if floor_cols[0] == 0 else 1), floor_cols[0]
    else:
        return [row[:] for row in grid]

    occupied = {(r, c) for r in range(h) for c in range(w) if grid[r][c] == 2}
    seen = set()
    objects = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or color == 2 or (r, c) in seen:
                continue
            cells = set()
            q = deque([(r, c)])
            seen.add((r, c))
            while q:
                rr, cc = q.popleft()
                cells.add((rr, cc))
                for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nr, nc = rr + dr, cc + dc
                    if (0 <= nr < h and 0 <= nc < w and (nr, nc) not in seen
                            and grid[nr][nc] == color):
                        seen.add((nr, nc))
                        q.append((nr, nc))
            objects.append((color, cells))

    if axis == 0:
        # Process objects nearest the platform first.
        objects.sort(key=lambda obj: min(r for r, _ in obj[1]) if direction < 0
                     else -max(r for r, _ in obj[1]))
        dr, dc = direction, 0
    else:
        objects.sort(key=lambda obj: min(c for _, c in obj[1]) if direction < 0
                     else -max(c for _, c in obj[1]))
        dr, dc = 0, direction

    out = [[0] * w for _ in range(h)]
    for r, c in occupied:
        out[r][c] = 2
    placed = set(occupied)
    for color, cells in objects:
        moved = set(cells)
        while True:
            nxt = {(r + dr, c + dc) for r, c in moved}
            if any(r < 0 or r >= h or c < 0 or c >= w or (r, c) in placed for r, c in nxt):
                break
            moved = nxt
        for r, c in moved:
            out[r][c] = color
            placed.add((r, c))
    return out


